```java
import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int t = scanner.nextInt();

        while (t-- > 0) {
            int n = scanner.nextInt();
            int k = scanner.nextInt();
            int[] a = new int[n + 1];
            long[] s = new long[n + 1];
            long[] dp = new long[n + 2];
            long[] udp = new long[n + 2];
            Arrays.fill(dp, -100000);
            Arrays.fill(udp, -100000);

            for (int i = 1; i <= n; i++) {
                a[i] = scanner.nextInt();
                s[i] = s[i - 1] + a[i];
            }

            for (int i = 1; i <= n; i++) {
                dp[i] = Math.max(a[i], dp[i - 1] + a[i]); // 计算最大前缀和
            }
            for (int i = 1; i <= n; i++) {
                dp[i] = Math.max(dp[i], dp[i - 1]); // 计算最大字段和
            }

            for (int i = n; i >= 1; i--) {
                udp[i] = Math.max(a[i], udp[i + 1] + a[i]); // 计算最大后缀和
            }
            for (int i = n; i >= 1; i--) {
                udp[i] = Math.max(udp[i + 1], udp[i]); // 计算最大字段和
            }

            long res = -2000000000;
            for (int i = 1; i + k + 1 <= n; i++) {
                res = Math.max(res, dp[i] + udp[i + k + 1]);
            }
            System.out.println(res);
        }
        scanner.close();
    }
}
